using System;using System.Data;
namespace AQOONHUB_SMS.Modules.Reports{public partial class SavedReports:ReportStage5Base{
 protected void Page_Load(object o,EventArgs e){if(!Require(ReportAuthorization.Saved))return;if(!IsPostBack)Bind();}
 void Bind(){var d=Repo.GetSavedReports(CurrentUserId,CurrentRole);gv.DataSource=d;gv.DataBind();litTotal.Text=d.Rows.Count.ToString();litPrivate.Text=d.Select("Visibility='Private'").Length.ToString();litRole.Text=d.Select("Visibility='Role-Based'").Length.ToString();litSchool.Text=d.Select("Visibility='School-Wide'").Length.ToString();litActive.Text=d.Select("Status='Active'").Length.ToString();litRecent.Text=d.Select("LastRunAt IS NOT NULL").Length.ToString();}
 protected void gv_RowCommand(object o,System.Web.UI.WebControls.GridViewCommandEventArgs e){int id;if(!int.TryParse(Convert.ToString(e.CommandArgument),out id))return;var r=Repo.GetSavedReport(id);if(r==null){Msg("Report not found.",false);return;}int owner=r["OwnerUserID"]==DBNull.Value?0:Convert.ToInt32(r["OwnerUserID"]);bool can=owner==CurrentUserId||ReportAuthorization.IsStage5Admin(CurrentRole);if(e.CommandName=="RunReport"){Response.Redirect("CustomReportBuilder.aspx?saved="+id,true);return;}if(e.CommandName=="DuplicateReport"){var v=ReportBuilderMetadata.Validate(Convert.ToString(r["ConfigurationJson"]),CurrentRole);if(!v.Valid){Msg(v.Message,false);return;}Repo.CreateSavedReport(Convert.ToString(r["ReportName"])+" (Copy)",Convert.ToString(r["ReportKey"]),Convert.ToString(r["Category"]),Convert.ToString(r["ConfigurationJson"]),"Private",CurrentUserId);Audit("Saved Report Duplicated",Convert.ToString(r["ReportKey"]),Convert.ToString(r["ReportName"])+" (Copy)",Convert.ToString(r["Category"]));}else if(e.CommandName=="ToggleReport"&&can){bool active=Convert.ToBoolean(r["IsActive"]);Repo.SetSavedReportActive(id,!active,CurrentUserId,CurrentRole);Audit(active?"Saved Report Disabled":"Saved Report Updated",Convert.ToString(r["ReportKey"]),Convert.ToString(r["ReportName"]),Convert.ToString(r["Category"]));}else if(e.CommandName=="DeleteReport"&&can){Repo.DeleteSavedReport(id,CurrentUserId,CurrentRole);Audit("Saved Report Deleted",Convert.ToString(r["ReportKey"]),Convert.ToString(r["ReportName"]),Convert.ToString(r["Category"]));}else Msg("You cannot modify another user's private report.",false);Bind();}
 void Msg(string m,bool ok){litMessage.Text="<div role='alert' class='s5-msg "+(ok?"s5-ok":"s5-error")+"'>"+ReportUi.Enc(m)+"</div>";}
}}
